
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_mpw1lyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_mpw1lyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.304660060579967e+00, -3.243198737159268e+00, -3.157128859414036e+00, -3.038008589421458e+00, -2.875913280776492e+00, -2.660622829793956e+00, -2.384386679290532e+00, -2.046753890664808e+00, -1.660395132748686e+00, -1.251275372017592e+00, -8.425847829784074e-01, -5.646273312499431e-01, -4.860033991523075e-01, -4.060855525478608e-01, -2.961080247054813e-01, -1.853069859942113e-01, -1.023952939306908e-01, -3.764592153391260e-02, -1.016808128294987e-03, -4.106769620472220e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


